# Xcode Cloud: runs right after the clone, before Xcode resolves packages and builds.
# The Xcode project is generated by XcodeGen (it is not in git), and the personal
# identifiers come from the workflow's environment variables instead of Config/Local.xcconfig.
set -eu

cd "$CI_PRIMARY_REPOSITORY_PATH"

# Required workflow environment variables (Xcode Cloud › workflow › Environment).
: "${BUNDLE_ID_PREFIX:?Set BUNDLE_ID_PREFIX in the Xcode Cloud workflow environment}"
: "${DEVELOPMENT_TEAM:?Set DEVELOPMENT_TEAM in the Xcode Cloud workflow environment}"

# swift-dependencies ships macros: Xcode Cloud can't approve them interactively.
defaults write com.apple.dt.Xcode IDESkipMacroFingerprintValidation -bool YES
defaults write com.apple.dt.Xcode IDESkipPackagePluginFingerprintValidatation -bool YES

# Identifiers, signing team and build number for this build.
cat > Config/Local.xcconfig <<XCCONFIG
BUNDLE_ID_PREFIX = $BUNDLE_ID_PREFIX
DEVELOPMENT_TEAM = $DEVELOPMENT_TEAM
CURRENT_PROJECT_VERSION = ${CI_BUILD_NUMBER:-1}
XCCONFIG

brew install xcodegen
xcodegen generate
